function makeNgrams(text, n = 3) {
  const lower = text.toLowerCase();
  const words = lower.match(/[a-z0-9_+\\-]+/g) || [];
  const grams = new Set();
  for (const w of words) {
    for (let i = 0; i + n <= w.length; i++) {
      grams.add(w.slice(i, i + n));
    }
  }
  return grams;
}

