function relevantChunks(engine, docs) {
  const chunks = new Set();
  for (const [chunkId, docId] of engine.chunkDocId) {
    if (!docId) continue;
    if (docs.has(docId) && !chunkId.endsWith('_full')) chunks.add(chunkId);
  }
  return chunks;
}

