function packingOptions(options) {
  const defaults = {
    budget: 250,
    bridgeCandidates: [],
    bridgeBoostMap: new Map(),
    lambda_decay: 2.2,
    alpha_l: 0.2,
    alpha_u: 0.05,
    w_bridge: 1.0,
    temporal_mode: false,
    reinforce_access: false,
    min_coverage: 0.315,
    rel_dropoff: 0.26,
  };
  const settings = { ...options };
  for (const [key, value] of Object.entries(defaults)) {
    if (options[key] === undefined) settings[key] = value;
  }

  return settings;
}

