function rankedPackingOptions(options = {}) {
  const defaults = {
    budget: 250,
    packer: "truncate",
    min_coverage: 0.315,
    rel_dropoff: 0.26,
    lambda_decay: 2.2,
    poolDepth: 100,
  };
  const settings = { ...options };
  for (const [key, value] of Object.entries(defaults)) {
    if (settings[key] === undefined) settings[key] = value;
  }
  settings.matchCache = new Map();

  return settings;
}

