function positiveRsjIdf(corpusSize, documentFrequency) {
  const M = Math.max(corpusSize, 1);
  const N = Math.min(Math.max(documentFrequency, 0), M);

  return Math.log1p((M - N + 0.5) / (N + 0.5));
}

